android.extraProguardRules:
# @livekit/react-native-webrtc references Chromium's JNI Zero classes but does not
# ship them, so R8 stops on "missing class". It only needs to be told not to warn.
-dontwarn livekit.org.jni_zero.**
# WebRTC and LiveKit classes are reached from native code, so R8 cannot see the uses.
-keep class livekit.org.jni_zero.** { *; }
-keep class livekit.org.webrtc.** { *; }
-keep class com.livekit.** { *; }
